class KickSynth
{
public:
    void noteOn(float velocity)
    {
        phase = 0.0f;
        ampEnv.noteOn();
        pitchEnv.noteOn();
        currentVelocity = velocity;
    }

    float process()
    {
        // Sine wave with pitch envelope
        auto freq = baseFreq * pitchEnv.getNextSample();
        phase += freq / sampleRate;

        float sample = std::sin(2.0f * M_PI * phase);
        sample *= ampEnv.getNextSample() * currentVelocity;

        return sample;
    }

private:
    float phase = 0.0f;
    float baseFreq = 60.0f;  // Fundamental
    float currentVelocity = 1.0f;
    ADSR ampEnv{10, 100, 0.5f, 200};  // ms
    ADSR pitchEnv{0, 50, 0.3f, 50};    // Pitch decay
};

// Layered kick: sine + click
float process()
{
    // Sub sine
    float sub = sineOsc.process() * subEnv.getNextSample();

    // Click transient
    float click = noise.process() * clickEnv.getNextSample();
    click = highpass.process(click);

    // Optional: transient from sample
    float transient = transientSample.process();

    return (sub + click * 0.3f + transient * 0.2f) * velocity;
}

class SnareSynth
{
public:
    SnareSynth()
    {
        // Tone component
        toneOsc.setFrequency(200.0f);

        // Noise component
        noiseEnv.setAttack(0);
        noiseEnv.setDecay(200);
        noiseEnv.setSustain(0.0f);
        noiseEnv.setRelease(50);

        // High-pass for noise
        highpass.setCutoffFrequency(2000.0f);
    }

    float process()
    {
        // Tone (body)
        float tone = toneOsc.process() * toneEnv.getNextSample();

        // Noise (snare wires)
        float noise = noiseGen.process() * noiseEnv.getNextSample();
        noise = highpass.process(noise);

        // Mix
        return tone * 0.4f + noise * 0.6f;
    }

private:
    Oscillator toneOsc;
    NoiseGenerator noiseGen;
    Filter highpass;
    ADSR toneEnv{5, 100, 0.3f, 100};
    ADSR noiseEnv{0, 200, 0.0f, 50};
};

class HiHatSynth
{
public:
    HiHatSynth()
    {
        // Multiple oscillators for metallic sound
        for (int i = 0; i < 6; ++i)
        {
            oscs[i].setFrequency(200.0f * (i + 1) * 1.5f);
        }

        // Very short envelope
        ampEnv.setAttack(0);
        ampEnv.setDecay(50);  // Open: 300ms
        ampEnv.setSustain(0.0f);
        ampEnv.setRelease(10);

        // High-pass for sizzle
        highpass.setCutoffFrequency(8000.0f);
    }

    float process()
    {
        float sample = 0.0f;

        // Sum detuned oscillators
        for (auto& osc : oscs)
        {
            sample += osc.process();
        }
        sample /= 6.0f;

        // Apply envelope and filter
        sample *= ampEnv.getNextSample();
        sample = highpass.process(sample);

        return sample;
    }

    void setOpen(bool isOpen)
    {
        if (isOpen)
            ampEnv.setDecay(300);
        else
            ampEnv.setDecay(50);
    }

private:
    Oscillator oscs[6];
    Filter highpass;
    ADSR ampEnv;
};

class ClapSynth
{
public:
    float process()
    {
        float sample = 0.0f;

        // Noise through bandpass
        float noise = noiseGen.process() * noiseEnv.getNextSample();
        noise = bandpass.process(noise);

        // Multiple "slap" transients
        // Simulated by delayed noise bursts
        for (int i = 0; i < 3; ++i)
        {
            if (transientEnv[i].isActive())
            {
                sample += noiseGen.process() * transientEnv[i].getNextSample();
            }
        }

        // Main clap body
        sample += noise;

        return sample * 0.3f;
    }

private:
    NoiseGenerator noiseGen;
    Filter bandpass;
    ADSR noiseEnv{0, 150, 0.2f, 100};
    ADSR transientEnv[3] = {
        ADSR{0, 10, 0.0f, 5},
        ADSR{0, 15, 0.0f, 5},
        ADSR{0, 20, 0.0f, 5}
    };
};

class TomSynth
{
public:
    TomSynth(float fundamental = 100.0f)
    {
        osc.setFrequency(fundamental);
        pitchEnv.setAttack(0);
        pitchEnv.setDecay(100);
        ampEnv.setAttack(5);
        ampEnv.setDecay(200);
    }

    float process()
    {
        // Pitch envelope for "thwack"
        float freqMod = pitchEnv.getNextSample();
        osc.setFrequency(baseFreq * (1.0f + freqMod * 0.5f));

        float sample = osc.process() * ampEnv.getNextSample();
        return sample;
    }

    void setPitch(float freq) { baseFreq = freq; }

private:
    Oscillator osc;
    ADSR pitchEnv{0, 100, 0.0f, 0};
    ADSR ampEnv{5, 200, 0.3f, 100};
    float baseFreq = 100.0f;
};

class RimshotSynth
{
public:
    float process()
    {
        // Two triangle waves detuned
        float osc1Out = osc1.process();
        float osc2Out = osc2.process();

        // Mix with filter
        float sample = (osc1Out + osc2Out) * 0.5f;
        sample = bandpass.process(sample);

        return sample * ampEnv.getNextSample();
    }

private:
    Oscillator osc1{Oscillator::triangleWave, 800.0f};
    Oscillator osc2{Oscillator::triangleWave, 540.0f};
    Filter bandpass;
    ADSR ampEnv{0, 50, 0.0f, 20};
};

